import { readFileSync } from 'node:fs'
import { escapeText } from './html.js'
import { renderInline } from './inline.js'
import { normalizeLabel } from './label.js'

const FENCE = /^(`{3,})([^`]*)$/
const HEADING = /^(#{1,6}) (.*)$/
const ITEM = /^( *)- (.*)$/
const DEFINITION = /^\[([^\]]+)\]:\s+(\S.*)$/

/** One refusal of a document line, carrying the 1-based line it was read at. */
export class BlockError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, message) {
    super(message)
    this.name = 'BlockError'
    this.line = line
  }
}

/**
 * Every input line, with the empty tail a trailing newline leaves dropped.
 * @param {string} text - the whole input.
 * @returns {string[]} the lines.
 */
export function splitLines(text) {
  const split = text.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

/**
 * Load a definitions file: one definition per line, blank lines and `#` lines ignored.
 * @param {string} path - the path to the definitions file.
 * @returns {Map<string, string>} normalized label to url.
 * @throws {Error} formatted for direct display, on a bad line, a duplicate label, or a read failure.
 */
export function loadDefinitionsFile(path) {
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    throw new Error(`cannot read definitions ${path}`)
  }
  const lines = splitLines(text)
  const definitions = new Map()
  for (let index = 0; index < lines.length; index += 1) {
    const number = index + 1
    const trimmed = lines[index].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const match = DEFINITION.exec(trimmed)
    if (match === null) throw new Error(`${path}: line ${number}: expected [label]: <url>`)
    const label = normalizeLabel(match[1])
    if (definitions.has(label)) throw new Error(`${path}: line ${number}: label ${label} is defined twice`)
    definitions.set(label, match[2])
  }
  return definitions
}

/**
 * The blocks of one document.
 * @param {string[]} lines - the document's lines.
 * @param {Map<string, string>} [fileDefinitions] - labels already defined by a definitions file.
 * @returns {{blocks: object[], definitions: Map<string, string>}} the blocks in document order, and the labels the document itself defined.
 * @throws {BlockError} on an unterminated fence or a label defined twice.
 */
export function parse(lines, fileDefinitions = new Map()) {
  const out = []
  const definitions = new Map()
  let paragraph = []
  let listRoot
  let levels
  const flush = () => {
    if (paragraph.length > 0) {
      out.push({ kind: 'paragraph', lines: paragraph })
      paragraph = []
    }
    if (listRoot !== undefined) {
      out.push({ kind: 'list', items: listRoot })
      listRoot = undefined
      levels = undefined
    }
  }
  for (let index = 0; index < lines.length; index += 1) {
    const raw = lines[index]
    const line = index + 1
    const fence = FENCE.exec(raw)
    if (fence !== null) {
      flush()
      const content = []
      let close = -1
      for (let scan = index + 1; scan < lines.length; scan += 1) {
        const candidate = lines[scan].trim()
        if (/^`{3,}$/u.test(candidate) && candidate.length >= fence[1].length) {
          close = scan
          break
        }
        content.push(lines[scan])
      }
      if (close === -1) throw new BlockError(line, 'unterminated code fence')
      out.push({ kind: 'fence', info: fence[2].trim().split(/\s+/u)[0], content })
      index = close
      continue
    }
    if (raw.trim() === '') {
      flush()
      continue
    }
    const definition = DEFINITION.exec(raw.trim())
    if (definition !== null) {
      flush()
      const label = normalizeLabel(definition[1])
      if (fileDefinitions.has(label) || definitions.has(label)) {
        throw new BlockError(line, `label ${label} is defined twice`)
      }
      definitions.set(label, definition[2])
      continue
    }
    const heading = HEADING.exec(raw)
    if (heading !== null) {
      flush()
      out.push({ kind: 'heading', level: heading[1].length, text: heading[2].trim() })
      continue
    }
    const item = ITEM.exec(raw)
    if (item !== null && paragraph.length === 0) {
      const level = Math.floor(item[1].length / 2)
      const text = item[2].trim()
      if (listRoot === undefined) {
        listRoot = []
        levels = [listRoot]
      }
      const capped = Math.min(level, levels.length)
      let target
      if (capped <= levels.length - 1) {
        levels.length = capped + 1
        target = levels[capped]
      } else {
        const parentArray = levels[levels.length - 1]
        const parentItem = parentArray[parentArray.length - 1]
        parentItem.children = []
        levels.push(parentItem.children)
        target = parentItem.children
      }
      target.push({ text })
      continue
    }
    if (listRoot !== undefined) flush()
    paragraph.push(raw.trim())
  }
  flush()
  return { blocks: out, definitions }
}

function renderItemLines(item, definitions) {
  if (item.children === undefined) return [`<li>${renderInline(item.text, definitions)}</li>`]
  return [`<li>${renderInline(item.text, definitions)}`, ...renderListLines(item.children, definitions), '</li>']
}

function renderListLines(items, definitions) {
  return ['<ul>', ...items.flatMap(item => renderItemLines(item, definitions)), '</ul>']
}

/**
 * Render parsed blocks to HTML.
 * @param {readonly object[]} parsed - the document's blocks.
 * @param {Map<string, string>} [definitions] - normalized label to url, for reference links.
 * @returns {string} the HTML, with a trailing newline unless the document holds no block.
 */
export function render(parsed, definitions = new Map()) {
  const rendered = parsed.map((block) => {
    if (block.kind === 'heading') return `<h${block.level}>${renderInline(block.text, definitions)}</h${block.level}>`
    if (block.kind === 'paragraph') return `<p>${block.lines.map(text => renderInline(text, definitions)).join('\n')}</p>`
    if (block.kind === 'list') return renderListLines(block.items, definitions).join('\n')
    const info = escapeText(block.info)
    const open = info === '' ? '<pre><code>' : `<pre><code class="language-${info}">`
    return `${open}${block.content.map(text => `${escapeText(text)}\n`).join('')}</code></pre>`
  })
  return rendered.length === 0 ? '' : `${rendered.join('\n')}\n`
}

/**
 * The headings of parsed blocks, for the outline.
 * @param {readonly object[]} parsed - the document's blocks.
 * @returns {{level: number, text: string}[]} the headings in document order.
 */
export function headings(parsed) {
  return parsed.filter(block => block.kind === 'heading').map(block => ({ level: block.level, text: block.text }))
}
"}

