const DEFINITION = /^\[([^\]]*)\]:\s+(\S.*)$/u

/**
 * The comparable form of a label: trimmed, its whitespace runs collapsed, and lowercased.
 * @param {string} label - the label as it was written.
 * @returns {string} the normalized label.
 */
export function normalizeLabel(label) {
  return label.trim().replaceAll(/\s+/gu, ' ').toLowerCase()
}

/**
 * Read one link definition, `[label]: url`, from an already trimmed line.
 * @param {string} line - the trimmed line.
 * @returns {{label: string, url: string}|undefined} the definition, or undefined when the line is not one.
 */
export function matchDefinition(line) {
  const found = DEFINITION.exec(line)
  if (found === null) return undefined
  return { label: normalizeLabel(found[1]), url: found[2] }
}
