/** The grammar a trimmed definition line follows: `[label]:` then whitespace then a non-empty url. */
export const DEFINITION_LINE = /^\[([^\]]*)\]:\s+(\S.*)$/u

/**
 * Normalize a label for comparison and lookup: trimmed, internal whitespace runs collapsed to
 * one space, and lowercased.
 * @param {string} label - the label as written.
 * @returns {string} the normalized label.
 */
export function normalizeLabel(label) {
  return label.trim().replace(/\s+/gu, ' ').toLowerCase()
}

/** One refusal of a definitions-file line, carrying the 1-based line it was read at. */
export class DefsError extends Error {
  /**
   * @param {number} line - the 1-based line within the definitions file.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, message) {
    super(message)
    this.name = 'DefsError'
    this.line = line
  }
}

/**
 * Parse a definitions file's own content into a map of definitions.
 * @param {string} text - the file's content.
 * @returns {Map<string, {url: string, source: string}>} normalized label to its definition.
 * @throws {DefsError} on a malformed line or a duplicate label.
 */
export function parseDefinitionsFile(text) {
  const defs = new Map()
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  for (let index = 0; index < lines.length; index += 1) {
    const line = index + 1
    const trimmed = lines[index].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const match = DEFINITION_LINE.exec(trimmed)
    if (match === null) throw new DefsError(line, 'expected [label]: <url>')
    const label = normalizeLabel(match[1])
    const url = match[2].trim()
    if (defs.has(label)) throw new DefsError(line, `label ${label} is defined twice`)
    defs.set(label, { url, source: 'file' })
  }
  return defs
}
