    } else {
      const parentArray = stack[stack.length - 1]
      const parentItem = parentArray[parentArray.length - 1]
      parentItem.children = []
      target = parentItem.children
    }
    stack.push(target)
  } else {
    stack.length = level + 1
    target = stack[stack.length - 1]
  }
  target.push({ text })
}

/**
 * The blocks of one document.
 * @param {string[]} lines - the document's lines.
 * @param {Map<string, {url: string, source: string}>} [defs] - definitions already in force
 *   (from a definitions file), extended with any the document itself defines.
 * @returns {{kind: string, level?: number, text?: string, lines?: string[], items?: object[], info?: string, content?: string[]}[]} the blocks in document order.
 * @throws {BlockError} on an unterminated fence or a label defined twice.
 */
export function parse(lines, defs = new Map()) {
  const out = []
  let paragraph = []
  let list
  const flush = () => {
    if (paragraph.length > 0) {
      out.push({ kind: 'paragraph', lines: paragraph })
      paragraph = []
    }
    if (list !== undefined) {
      out.push({ kind: 'list', items: list.items })
      list = undefined
    }
  }
  for (let index = 0; index < lines.length; index += 1) {
    const raw = lines[index]
    const line = index + 1
    const fence = FENCE.exec(raw)
    if (fence !== null) {
      flush()
      const content = []
      let close = -1
      for (let scan = index + 1; scan < lines.length; scan += 1) {
        const candidate = lines[scan].trim()
        if (/^`{3,}$/u.test(candidate) && candidate.length >= fence[1].length) {
          close = scan
          break
        }
        content.push(lines[scan])
      }
      if (close === -1) throw new BlockError(line, 'unterminated code fence')
      out.push({ kind: 'fence', info: fence[2].trim().split(/\s+/u)[0], content })
      index = close
      continue
    }
    if (raw.trim() === '') {
      flush()
      continue
    }
    const heading = HEADING.exec(raw)
    if (heading !== null) {
      flush()
      out.push({ kind: 'heading', level: heading[1].length, text: heading[2].trim() })
      continue
    }
    const trimmed = raw.trim()
    const definition = DEFINITION_LINE.exec(trimmed)
    if (definition !== null) {
      flush()
      const label = normalizeLabel(definition[1])
      const url = definition[2].trim()
      if (defs.has(label)) throw new BlockError(line, `label ${label} is defined twice`)
      defs.set(label, { url, source: 'document' })
      continue
    }
    const item = ITEM.exec(raw)
    if (item !== null && paragraph.length === 0) {
      const rawLevel = Math.floor(item[1].length / 2)
      const text = item[2].trim()
      if (list === undefined) list = { items: [], stack: [] }
      addItem(list, text, rawLevel)
      continue
    }
    if (list !== undefined) flush()
    paragraph.push(raw.trim())
  }
  flush()
  return out
