/**
 * Render one nested list to its `<ul>` HTML.
 * @param {object[]} items - the list's items, each possibly holding `children`.
 * @param {Map<string, {url: string, source: string}>} defs - the definitions in force.
 * @returns {string} the `<ul>...</ul>` block.
 */
function renderList(items, defs) {
  const lines = []
  for (const item of items) {
    if (item.children !== undefined) {
      lines.push(`<li>${renderInline(item.text, defs)}`)
      lines.push(renderList(item.children, defs))
      lines.push('</li>')
    } else {
      lines.push(`<li>${renderInline(item.text, defs)}</li>`)
    }
  }
  return ['<ul>', ...lines, '</ul>'].join('\n')
