/** The command: `html`, `outline`, and `defs`, each over the document on standard input, with an
 * optional definitions file named as a second argument. */

import { readFileSync } from 'node:fs'
import { BlockError, headings, parse, render, splitLines } from './block.js'
import { DefsError, parseDefinitionsFile } from './defs.js'

const USAGE = 'usage: cli.js html|outline|defs [<definitions>]'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
const mode = argv[0]
if (!['html', 'outline', 'defs'].includes(mode) || argv.length < 1 || argv.length > 2) fail(USAGE)

const defsPath = argv[1]
let defs = new Map()
if (defsPath !== undefined) {
  let text
  try {
    text = readFileSync(defsPath, 'utf8')
  } catch {
    fail(`cannot read definitions ${defsPath}`)
  }
  try {
    defs = parseDefinitionsFile(text)
  } catch (error) {
    if (!(error instanceof DefsError)) throw error
    fail(`${defsPath}: line ${error.line}: ${error.message}`)
  }
}

let parsed
try {
  parsed = parse(splitLines(readFileSync(0, 'utf8')), defs)
} catch (error) {
  if (!(error instanceof BlockError)) throw error
  fail(`line ${error.line}: ${error.message}`)
}

if (mode === 'html') {
  process.stdout.write(render(parsed, defs))
} else if (mode === 'outline') {
  process.stdout.write(headings(parsed).map(one => `${one.level} ${one.text}\n`).join(''))
} else {
  const entries = [...defs.entries()].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  const lines = entries.map(([label, definition]) => `${label} ${definition.url} ${definition.source}\n`)
  process.stdout.write(`${lines.join('')}total ${entries.length}\n`)
}
"}

