 * @returns {string[]|null} the cycle's names, or null when the graph is acyclic.
 */
export function findCycle(tasks) {
  const done = new Set()
  const onStack = new Set()
  const stack = []
  let cycle = null

  function visit(name) {
    if (cycle !== null) return
    if (onStack.has(name)) {
      cycle = [...stack.slice(stack.indexOf(name)), name]
      return
    }
    if (done.has(name)) return
    onStack.add(name)
    stack.push(name)
    for (const need of [...tasks.get(name).needs].sort()) {
      visit(need)
      if (cycle !== null) return
