{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/** The command: `order`, `show <name>`, `files <name>`, `digest <path>...` and `plan <snapshot>`. */

import { existsSync, readFileSync } from 'node:fs'
import { digestBytes } from './digest.js'
import { findCycle, order, watched } from './graph.js'
import { parse, ParseError, splitLines } from './parse.js'
import { parseSnapshot, SnapshotError } from './snapshot.js'

const USAGE = 'usage: cli.js order|show <name>|files <name>|digest <path>...|plan <snapshot>'

/** Report one failure the way the specification words it, and stop. */
function fail(message, code = 2) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(code)
}

/** One `show` or `files` field, with `-` standing for an empty list. */
function field(label, values) {
  return `${label}: ${values.length === 0 ? '-' : [...values].sort().join(' ')}`
}

/** The digest of a workspace file, or null when there is no such file to read. */
function fileDigest(path) {
  if (!existsSync(path)) return null
  try {
    return digestBytes(readFileSync(path))
  } catch {
    return null
  }
}

/** Refuse a cyclic graph, naming the cycle the search found. */
function refuseCycle(tasks) {
  const cycle = findCycle(tasks)
  if (cycle !== null) fail(`cycle: ${cycle.join(' -> ')}`, 3)
}

/** The task a name declares, or a refusal when no `task` line declares it. */
function lookup(tasks, name) {
  const task = tasks.get(name)
  if (task === undefined) fail(`unknown task ${name}`)
  return task
}

/**
 * Why a task must run under a snapshot, or null when nothing condemns it. The first
 * watched path with a reason decides; failing that, the smallest dependency that runs.
 */
function reasonFor(task, recorded, running) {
  for (const path of watched(task)) {
    const digest = recorded.get(path)
    if (digest === undefined) return `new ${path}`
    const actual = fileDigest(path)
    if (actual === null) return `missing ${path}`
    if (actual !== digest) return `changed ${path}`
  }
  const deps = [...task.needs].filter(need => running.has(need)).sort()
  return deps.length === 0 ? null : `needs ${deps[0]}`
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { order: 1, show: 2, files: 2, plan: 2 }
if (mode === 'digest' ? argv.length < 2 : argv.length !== arity[mode]) fail(USAGE)

let tasks
try {
  tasks = parse(splitLines(readFileSync(0, 'utf8')))
} catch (error) {
  if (!(error instanceof ParseError)) throw error
  fail(error.line === 0 ? error.message : `line ${error.line}: ${error.message}`)
}

const out = []
if (mode === 'order') {
  refuseCycle(tasks)
  for (const name of order(tasks)) out.push(name)
} else if (mode === 'show') {
  const task = lookup(tasks, argv[1])
  out.push(`${task.name}: ${task.command}`)
  out.push(field('needs', task.needs))
} else if (mode === 'files') {
  const task = lookup(tasks, argv[1])
  out.push(field('reads', task.reads))
  out.push(field('writes', task.writes))
} else if (mode === 'plan') {
  const path = argv[1]
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    fail(`cannot read snapshot ${path}`)
  }
  let recorded
  try {
    recorded = parseSnapshot(text)
  } catch (error) {
    if (!(error instanceof SnapshotError)) throw error
    fail(`${path}: line ${error.line}: ${error.message}`)
  }
  refuseCycle(tasks)
  const running = new Set()
  let runs = 0
  let skips = 0
  for (const name of order(tasks)) {
    const reason = reasonFor(tasks.get(name), recorded, running)
    if (reason === null) {
      skips += 1
      out.push(`skip ${name}`)
    } else {
      running.add(name)
      runs += 1
      out.push(`run ${name} ${reason}`)
    }
  }
  out.push(`total run=${runs} skip=${skips}`)
} else {
  for (const path of argv.slice(1)) {
    out.push(`${path} ${existsSync(path) ? digestBytes(readFileSync(path)) : 'missing'}`)
  }
}
process.stdout.write(out.map(line => `${line}\n`).join(''))
"}

